        "明日の 喜びを運んで",
        "全部 風が連れてゆく",
        "或るべき場所へ"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "吹き荒れて 流れ流れ",
        "今はもうこんなところ",
        "飛ばされて ゆらり揺られ",
        "ふと思う ここはどこ"
      ]
    }
  ],
