      ]
    },
    {
      "id": "B1-03",
      "ja": "飛ばされて ゆらり揺られ",
      "budget": {
        "min": 11,
        "max": 11
      },
      "pattern": [
        5,
        3,
        3
      ]
    },
    {
      "id": "B1-04",
      "ja": "ふと思う ここはどこ",
      "budget": {
        "min": 10,
