      },
      "pattern": [
        2,
        3,
        3,
        2
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "狂风呼啸着 漂泊流浪"
        },
        {
          "id": "B1-02",
          "zh": "如今已到 这般境地"
        },
        {
          "id": "B1-03",
          "zh": "被吹散去 轻轻摇晃着"
        },
        {
          "id": "B1-04",
          "zh": "忽然想到 这是何处"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风灌满衣裳 吹又吹 流又流"
        },
        {
          "id": "B1-02",
          "zh": "如今我 已在 这么个小角落"
        },
        {
          "id": "B1-03",
          "zh": "风把我抛起 轻轻摇 缓缓晃"
        },
        {
          "id": "B1-04",
          "zh": "忽然 笑出声 这儿是 哪儿"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风呼啸 飘零飘零"
        },
        {
          "id": "B1-02",
          "zh": "此刻已 身在何处"
        },
        {
          "id": "B1-03",
          "zh": "被吹散 轻轻摇荡"
        },
        {
          "id": "B1-04",
          "zh": "忽念起 此处何方"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风卷过长街 尘沙起 纸屑飞"
        },
        {
          "id": "B1-02",
          "zh": "这时候 何处 路牌全都沉睡"
        },
        {
          "id": "B1-03",
          "zh": "被风吹起来 轻轻晃 慢慢摇"
        },
        {
          "id": "B1-04",
          "zh": "忽然 睁开眼 天地间 何处"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "狂风呼啸 漂流流转"
        },
        {
          "id": "B1-02",
          "zh": "如今已到 这般地方"
        },
        {
          "id": "B1-03",
          "zh": "被吹散 轻轻摇荡"
        },
        {
          "id": "B1-04",
          "zh": "忽然想问 这里是何处"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "风呼啸 吹过 又吹过"
        },
        {
          "id": "B1-02",
          "zh": "如今 身在 这样荒凉地方"
        },
        {
          "id": "B1-03",
          "zh": "被吹散 摇摇 又晃晃"
        },
        {
          "id": "B1-04",
          "zh": "忽觉 此处 是何处"
        }
      ]
    }
  ]
}

